crates/vb_storage/src/executor/issuance_tests.rs:22: // Case 2a: Strict policy submit returns sequence 1.
crates/vb_storage/src/executor/issuance_tests.rs:23: #[test]
crates/vb_storage/src/executor/issuance_tests.rs:24: fn strict_submit_sequence_one() -> TestResult {
crates/vb_storage/src/executor/issuance_tests.rs:25:     let fixture = PackedFixture::new()?;
