crates/vb_storage/src/executor/issuance_tests.rs:27:     let artifact = fixture.submit(&journal, RuntimePolicy::Strict)?;
crates/vb_storage/src/executor/issuance_tests.rs:28:     if artifact.sequence_number != 1 {
crates/vb_storage/src/executor/issuance_tests.rs:29:         return Err("strict submit should yield sequence 1".into());
crates/vb_storage/src/executor/issuance_tests.rs:30:     }
crates/vb_storage/src/executor/issuance_tests.rs:31:     fixture.check(&journal, &artifact, RuntimePolicy::Strict)
crates/vb_storage/src/executor/issuance_tests.rs:32: }
