    let artifact = fixture.submit(&journal, RuntimePolicy::Strict)?;
    if artifact.sequence_number != 1 {
        return Err("strict submit should yield sequence 1".into());
    }
    fixture.check(&journal, &artifact, RuntimePolicy::Strict)
